using System.Buffers;
using System.IO.Compression;
using System.Security.Cryptography;
using System.Text.Json;
using System.Text.Json.Serialization;
using TOOL_SHARED.Contracts.Updates;

namespace TOOL_SHARED.Distribution.Updates;

public sealed record DesktopPackageArchiveLayout(string PayloadRoot,
    IReadOnlyDictionary<string, ZipArchiveEntry> Files, long ExpandedSizeBytes, int EntryCount);

/// <summary>Metadata generated by the API for an unchanged, ordinary Publish ZIP.</summary>
public static class DesktopPackageMetadataPolicy
{
    public const int MaximumMetadataBytes = 4 * 1024 * 1024;
    public const string MinimumBootstrapperVersion = "1.1.0";
    private static readonly string[] GeneratedFiles =
        ["update-manifest.json", "distribution-profile.json", "package-inventory.json"];
    private static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web)
    { PropertyNameCaseInsensitive = false, UnmappedMemberHandling = JsonUnmappedMemberHandling.Disallow, MaxDepth = 32 };

    public static string MetadataPath(Guid releaseId, Guid bootstrapperId, string sha256) =>
        $"api/launcher-distribution/versions/{releaseId:D}/bootstrappers/{bootstrapperId:D}/package-metadata/{sha256.ToLowerInvariant()}";

    public static void ValidateReference(DesktopReleaseResponse release, Uri apiOrigin)
    {
        if (release.PackageMetadata is not { } reference) return;
        if (release.ReleaseId == Guid.Empty || release.DistributionProtocol != DesktopDistributionProtocol.Shared
            || release.SharedBootstrapper is null || release.SharedBootstrapper.BootstrapperId == Guid.Empty
            || reference.SchemaVersion != 1 || reference.SizeBytes is <= 0 or > MaximumMetadataBytes
            || !IsHash(reference.Sha256) || !IsHash(reference.ArchiveSha256)
            || !reference.ArchiveSha256.Equals(release.Sha256, StringComparison.OrdinalIgnoreCase)
            || !DesktopReleaseVersionPolicy.IsSupportedStableVersion(release.MinimumBootstrapperVersion)
            || DesktopReleaseVersionPolicy.CompareVersions(release.MinimumBootstrapperVersion, MinimumBootstrapperVersion) < 0)
            throw Invalid();
        var actual = DesktopArtifactDownloadPolicy.Validate(apiOrigin, reference.DownloadUrl, DesktopArtifactSourceKinds.Internal);
        var expected = new Uri(apiOrigin, MetadataPath(release.ReleaseId, release.SharedBootstrapper.BootstrapperId, reference.Sha256));
        if (actual != expected) throw Invalid();
    }

    public static byte[] SerializeDocument(DesktopPackageMetadataDocument document)
    {
        ValidateDocument(document);
        var bytes = JsonSerializer.SerializeToUtf8Bytes(document, Json);
        if (bytes.Length > MaximumMetadataBytes) throw Invalid();
        return bytes;
    }

    public static DesktopPackageMetadataDocument DeserializeDocument(ReadOnlyMemory<byte> bytes)
    {
        if (bytes.Length is <= 0 or > MaximumMetadataBytes) throw Invalid();
        try
        {
            using var parsed = JsonDocument.Parse(bytes, new JsonDocumentOptions { MaxDepth = 32 });
            RejectDuplicates(parsed.RootElement);
            var document = parsed.RootElement.Deserialize<DesktopPackageMetadataDocument>(Json) ?? throw Invalid();
            ValidateDocument(document);
            return document;
        }
        catch (JsonException error) { throw new InvalidDataException("Package metadata is invalid.", error); }
    }

    public static void ValidateDocument(DesktopPackageMetadataDocument document)
    {
        if (document is null || document.SchemaVersion != 1 || !IsHash(document.ArchiveSha256)
            || document.PayloadRoot is null || document.ExpandedSizeBytes is <= 0 or > DesktopArtifactDownloadPolicy.MaximumExpandedBytes
            || document.EntryCount is <= 0 or > DesktopArtifactDownloadPolicy.MaximumEntryCount
            || document.Files is null || document.Files.Count is <= 0 or > DesktopArtifactDownloadPolicy.MaximumEntryCount - 4
            || document.EntryCount < document.Files.Count) throw Invalid();
        ValidatePrefix(document.PayloadRoot);
        var manifest = document.Manifest;
        var profile = document.DistributionProfile;
        if (manifest is null || manifest.Product != "VideoMaker" || manifest.Platform != "win-x64"
            || manifest.BuildNumber <= 0 || !DesktopReleaseVersionPolicy.IsSupportedStableVersion(manifest.Version)
            || manifest.ManagedFiles is null || profile is null || profile.SchemaVersion != 1
            || profile.DistributionProtocol != DesktopDistributionProtocol.Shared || profile.Platform != "win-x64"
            || profile.Channel != "Stable" || string.IsNullOrWhiteSpace(profile.Profile) || profile.Profile.Length > 50
            || string.IsNullOrWhiteSpace(profile.ModelBundleId)
            || !DesktopReleaseVersionPolicy.IsSupportedStableVersion(profile.MinimumBootstrapperVersion)
            || DesktopReleaseVersionPolicy.CompareVersions(profile.MinimumBootstrapperVersion, MinimumBootstrapperVersion) < 0
            || !Uri.TryCreate(profile.ServerBaseUrl, UriKind.Absolute, out var api)
            || api.Scheme != "https" || api.IsLoopback || api.UserInfo.Length != 0 || api.Query.Length != 0 || api.Fragment.Length != 0)
            throw Invalid();
        var files = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        long size = 0;
        foreach (var file in document.Files)
        {
            if (file is null || !files.Add(NormalizeRelativePath(file.Path)) || !IsHash(file.Sha256)
                || file.SizeBytes < 0 || file.SizeBytes > DesktopArtifactDownloadPolicy.MaximumExpandedBytes
                || size > DesktopArtifactDownloadPolicy.MaximumExpandedBytes - file.SizeBytes
                || GeneratedFiles.Contains(file.Path, StringComparer.OrdinalIgnoreCase) || IsPrivateFile(file.Path)) throw Invalid();
            size += file.SizeBytes;
        }
        if (size != document.ExpandedSizeBytes || !files.Contains("TOOL-LOCAL.exe") || !files.Contains("appsettings.json")
            || document.Files.Any(x => (x.Path.Equals("TOOL-LOCAL.exe", StringComparison.OrdinalIgnoreCase)
                || x.Path.Equals("appsettings.json", StringComparison.OrdinalIgnoreCase)) && x.SizeBytes == 0)) throw Invalid();
        AssertNoFileParents(files);
        var managed = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var path in manifest.ManagedFiles)
            if (!managed.Add(NormalizeRelativePath(path))) throw Invalid();
        files.UnionWith(GeneratedFiles);
        AssertNoFileParents(files);
        if (!managed.SetEquals(files)) throw Invalid();
    }

    public static void ValidateDocument(DesktopPackageMetadataDocument document, DesktopReleaseResponse release)
    {
        ValidateDocument(document);
        var reference = release.PackageMetadata ?? throw Invalid();
        if (release.SharedBootstrapper is null) throw Invalid();
        ValidateReference(release, new Uri(release.SharedBootstrapper.ApiBaseUrl));
        var p = document.DistributionProfile;
        if (!document.ArchiveSha256.Equals(release.Sha256, StringComparison.OrdinalIgnoreCase)
            || document.Manifest.Version != release.Version || document.Manifest.BuildNumber != release.BuildNumber
            || document.Manifest.Product != release.ProductName || document.Manifest.Platform != release.Platform
            || p.Profile != release.Profile || p.Channel != release.Channel || p.Platform != release.Platform
            || p.ModelBundleId != release.ModelBundleId || p.MinimumBootstrapperVersion != release.MinimumBootstrapperVersion
            || !DesktopSharedBootstrapperPolicy.SameApi(new Uri(p.ServerBaseUrl), new Uri(release.SharedBootstrapper.ApiBaseUrl))) throw Invalid();
        var bytes = SerializeDocument(document);
        if (bytes.LongLength != reference.SizeBytes || !Convert.ToHexString(SHA256.HashData(bytes)).Equals(reference.Sha256, StringComparison.OrdinalIgnoreCase))
            throw Invalid();
    }

    public static DesktopPackageArchiveLayout InspectLayout(ZipArchive archive)
    {
        if (archive.Entries.Count is <= 0 or > DesktopArtifactDownloadPolicy.MaximumEntryCount) throw Invalid();
        var paths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var directories = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var entries = new Dictionary<string, ZipArchiveEntry>(StringComparer.OrdinalIgnoreCase);
        long expanded = 0;
        foreach (var entry in archive.Entries)
        {
            var directory = entry.FullName.EndsWith('/');
            var path = NormalizeRelativePath(directory ? entry.FullName[..^1] : entry.FullName);
            var kind = (entry.ExternalAttributes >> 16) & 0xf000;
            if ((entry.ExternalAttributes & 0x400) != 0 || kind is not (0 or 0x8000 or 0x4000)
                || kind == 0x4000 && !directory || kind == 0x8000 && directory || !paths.Add(path)) throw Invalid();
            if (directory)
            {
                if (entry.Length != 0) throw Invalid();
                directories.Add(path);
            }
            else
            {
                if (entry.Length < 0 || entry.Length > DesktopArtifactDownloadPolicy.MaximumExpandedBytes
                    || expanded > DesktopArtifactDownloadPolicy.MaximumExpandedBytes - entry.Length) throw Invalid();
                expanded += entry.Length;
                entries.Add(path, entry);
            }
        }
        if (expanded <= 0 || entries.Count == 0) throw Invalid();
        AssertNoFileParents(entries.Keys);
        foreach (var directory in directories)
        {
            for (var parent = directory; parent.Contains('/');)
            {
                parent = parent[..parent.LastIndexOf('/')];
                if (entries.ContainsKey(parent)) throw Invalid();
            }
        }
        var application = entries.Keys.Where(x => Path.GetFileName(x) == "TOOL-LOCAL.exe").ToArray();
        if (application.Length != 1) throw Invalid();
        var app = application[0];
        var separator = app.LastIndexOf('/');
        var prefix = separator < 0 ? "" : app[..(separator + 1)];
        ValidatePrefix(prefix);
        var relative = new Dictionary<string, ZipArchiveEntry>(StringComparer.OrdinalIgnoreCase);
        foreach (var (path, entry) in entries)
        {
            if (!path.StartsWith(prefix, StringComparison.Ordinal)) throw Invalid();
            var name = NormalizeRelativePath(path[prefix.Length..]);
            if (!relative.TryAdd(name, entry)) throw Invalid();
        }
        if (prefix.Length > 0 && directories.Any(x => x != prefix[..^1] && !x.StartsWith(prefix, StringComparison.Ordinal))) throw Invalid();
        return new(prefix, relative, expanded, archive.Entries.Count);
    }

    public static string NormalizeRelativePath(string path)
    {
        if (string.IsNullOrWhiteSpace(path) || path.Length > 260 || path.Contains('\\') || path.Contains(':')
            || path.Any(c => char.IsControl(c) || "<>\"|?*".Contains(c))) throw Invalid();
        foreach (var segment in path.Split('/'))
        {
            if (segment is "" or "." or ".." || segment.EndsWith('.') || segment.EndsWith(' ')) throw Invalid();
            var name = segment.Split('.')[0];
            if (name.Equals("CON", StringComparison.OrdinalIgnoreCase) || name.Equals("PRN", StringComparison.OrdinalIgnoreCase)
                || name.Equals("AUX", StringComparison.OrdinalIgnoreCase) || name.Equals("NUL", StringComparison.OrdinalIgnoreCase)
                || name.Length == 4 && name[3] is >= '1' and <= '9'
                    && (name.StartsWith("COM", StringComparison.OrdinalIgnoreCase) || name.StartsWith("LPT", StringComparison.OrdinalIgnoreCase))) throw Invalid();
        }
        return path;
    }

    public static async Task ExtractAndMaterializeAsync(string archivePath, string stageRoot,
        DesktopReleaseResponse release, DesktopPackageMetadataDocument document, CancellationToken token)
    {
        ValidateDocument(document, release);
        await ExtractCoreAsync(archivePath, stageRoot, release, document, token);
    }

    internal static async Task ExtractVerifiedLocalAsync(string archivePath, string stageRoot,
        DesktopReleaseResponse release, DesktopPackageMetadataDocument document, CancellationToken token)
    {
        ValidateDocument(document);
        DesktopSharedBootstrapperPolicy.ValidateRelease(release);
        var p = document.DistributionProfile;
        if (release.PackageMetadata is not null || document.ArchiveSha256 != release.Sha256
            || document.Manifest.Version != release.Version || document.Manifest.BuildNumber != release.BuildNumber
            || p.Profile != release.Profile || p.Channel != release.Channel || p.Platform != release.Platform
            || p.ModelBundleId != release.ModelBundleId || p.MinimumBootstrapperVersion != release.MinimumBootstrapperVersion
            || !DesktopSharedBootstrapperPolicy.SameApi(new Uri(p.ServerBaseUrl), new Uri(release.SharedBootstrapper!.ApiBaseUrl))) throw Invalid();
        await ExtractCoreAsync(archivePath, stageRoot, release, document, token);
    }

    internal static async Task ExtractVerifiedStandaloneAsync(string archivePath, string stageRoot,
        DesktopReleaseResponse release, DesktopPackageMetadataDocument document, CancellationToken token)
    {
        ValidateDocument(document);
        var p = document.DistributionProfile;
        DesktopStandaloneCatalogPolicy.ValidateMeasuredPackage(release, new Uri(p.ServerBaseUrl));
        if (document.ArchiveSha256 != release.Sha256 || document.Manifest.Version != release.Version
            || document.Manifest.BuildNumber != release.BuildNumber || p.Profile != release.Profile
            || p.Channel != release.Channel || p.Platform != release.Platform || p.ModelBundleId != release.ModelBundleId
            || p.MinimumBootstrapperVersion != release.MinimumBootstrapperVersion) throw Invalid();
        await ExtractCoreAsync(archivePath, stageRoot, release, document, token);
    }

    private static async Task ExtractCoreAsync(string archivePath, string stageRoot,
        DesktopReleaseResponse release, DesktopPackageMetadataDocument document, CancellationToken token)
    {
        AssertSafePath(archivePath); AssertSafePath(stageRoot);
        var stage = Path.TrimEndingDirectorySeparator(Path.GetFullPath(stageRoot));
        if (Directory.Exists(stage) && Directory.EnumerateFileSystemEntries(stage).Any()) throw Invalid();
        await using var file = new FileStream(archivePath, FileMode.Open, FileAccess.Read, FileShare.Read, 81920, FileOptions.Asynchronous);
        if (file.Length != release.SizeBytes || file.Length > DesktopArtifactDownloadPolicy.MaximumAppArchiveBytes
            || !Convert.ToHexString(await SHA256.HashDataAsync(file, token)).Equals(release.Sha256, StringComparison.OrdinalIgnoreCase)) throw Invalid();
        file.Position = 0;
        using var archive = new ZipArchive(file, ZipArchiveMode.Read, leaveOpen: true);
        var layout = InspectLayout(archive);
        if (layout.PayloadRoot != document.PayloadRoot || layout.EntryCount != document.EntryCount
            || layout.ExpandedSizeBytes != document.ExpandedSizeBytes || layout.Files.Count != document.Files.Count) throw Invalid();
        foreach (var expected in document.Files)
            if (!layout.Files.TryGetValue(expected.Path, out var entry) || entry.Length != expected.SizeBytes) throw Invalid();
        var drive = new DriveInfo(Path.GetPathRoot(stage)!);
        var generatedReserve = 3L * MaximumMetadataBytes + 64L * 1024 * 1024;
        if (drive.AvailableFreeSpace < document.ExpandedSizeBytes + generatedReserve)
            throw new IOException("Insufficient free disk space for the approved application payload.");
        Directory.CreateDirectory(stage); AssertSafePath(stage);
        var buffer = ArrayPool<byte>.Shared.Rent(81920);
        try
        {
            foreach (var expected in document.Files)
            {
                token.ThrowIfCancellationRequested();
                var entry = layout.Files[expected.Path];
                var target = SafeChild(stage, expected.Path);
                Directory.CreateDirectory(Path.GetDirectoryName(target)!); AssertSafePath(target);
                await using var output = new FileStream(target, FileMode.CreateNew, FileAccess.Write, FileShare.None, 81920, FileOptions.Asynchronous);
                await using var input = entry.Open();
                using var sha = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
                long bytes = 0;
                int count;
                while ((count = await input.ReadAsync(buffer.AsMemory(0, buffer.Length), token)) > 0)
                {
                    bytes += count;
                    if (bytes > expected.SizeBytes) throw Invalid();
                    sha.AppendData(buffer, 0, count);
                    await output.WriteAsync(buffer.AsMemory(0, count), token);
                }
                if (bytes != expected.SizeBytes || !Convert.ToHexString(sha.GetHashAndReset()).Equals(expected.Sha256, StringComparison.OrdinalIgnoreCase)) throw Invalid();
            }
        }
        finally { ArrayPool<byte>.Shared.Return(buffer); }
        // The original ZIP never needs rewriting. These files are generated only
        // after its exact bytes and every source file have passed verification.
        var manifestBytes = JsonSerializer.SerializeToUtf8Bytes(document.Manifest, Json);
        var profileBytes = JsonSerializer.SerializeToUtf8Bytes(document.DistributionProfile, Json);
        var inventoryFiles = document.Files.Concat(new[]
        {
            Stamp("update-manifest.json", manifestBytes), Stamp("distribution-profile.json", profileBytes)
        }).OrderBy(x => x.Path, StringComparer.Ordinal).ToArray();
        var inventoryBytes = JsonSerializer.SerializeToUtf8Bytes(new
        { schemaVersion = 1, excludes = new[] { "package-inventory.json" }, files = inventoryFiles }, Json);
        if (manifestBytes.Length > MaximumMetadataBytes || profileBytes.Length > MaximumMetadataBytes || inventoryBytes.Length > MaximumMetadataBytes) throw Invalid();
        await WriteGeneratedAsync(stage, "update-manifest.json", manifestBytes, token);
        await WriteGeneratedAsync(stage, "distribution-profile.json", profileBytes, token);
        await WriteGeneratedAsync(stage, "package-inventory.json", inventoryBytes, token);
    }

    private static DesktopPackageFileHash Stamp(string path, byte[] bytes) => new(path, bytes.LongLength,
        Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant());
    private static async Task WriteGeneratedAsync(string root, string name, byte[] bytes, CancellationToken token)
    {
        var target = SafeChild(root, name); AssertSafePath(target);
        await using var output = new FileStream(target, FileMode.CreateNew, FileAccess.Write, FileShare.None, 81920, FileOptions.Asynchronous);
        await output.WriteAsync(bytes, token);
    }
    private static void ValidatePrefix(string prefix)
    {
        if (prefix == "") return;
        if (!prefix.EndsWith('/') || prefix.Count(c => c == '/') != 1) throw Invalid();
        NormalizeRelativePath(prefix[..^1]);
    }
    private static void AssertNoFileParents(IEnumerable<string> filePaths)
    {
        var files = filePaths.ToHashSet(StringComparer.OrdinalIgnoreCase);
        foreach (var file in files)
            for (var path = file; path.Contains('/');)
            { path = path[..path.LastIndexOf('/')]; if (files.Contains(path)) throw Invalid(); }
    }
    private static bool IsPrivateFile(string path) => path.Split('/').Any(segment => segment.Equals(".git", StringComparison.OrdinalIgnoreCase)
        || segment.Equals(".vs", StringComparison.OrdinalIgnoreCase) || segment.Equals("node_modules", StringComparison.OrdinalIgnoreCase))
        || path.Equals("appsettings.user.json", StringComparison.OrdinalIgnoreCase)
        || path.Equals("static-setup-receipt.json", StringComparison.OrdinalIgnoreCase) || Path.GetFileName(path).Equals(".env", StringComparison.OrdinalIgnoreCase);
    private static string SafeChild(string root, string relative)
    {
        NormalizeRelativePath(relative);
        var target = Path.GetFullPath(Path.Combine(root, relative.Replace('/', Path.DirectorySeparatorChar)));
        if (!target.StartsWith(root + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase)) throw Invalid();
        return target;
    }
    private static void AssertSafePath(string path)
    {
        var full = Path.GetFullPath(path);
        for (FileSystemInfo? item = File.Exists(full) ? new FileInfo(full) : new DirectoryInfo(full); item is not null;
            item = item is DirectoryInfo directory ? directory.Parent : new DirectoryInfo(Path.GetDirectoryName(item.FullName)!))
            if (item.Exists && (item.Attributes & FileAttributes.ReparsePoint) != 0) throw Invalid();
    }
    private static bool IsHash(string? value) => value is { Length: 64 } && value.All(char.IsAsciiHexDigit);
    private static void RejectDuplicates(JsonElement element)
    {
        if (element.ValueKind == JsonValueKind.Object)
        {
            var names = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var property in element.EnumerateObject())
            { if (!names.Add(property.Name)) throw Invalid(); RejectDuplicates(property.Value); }
        }
        else if (element.ValueKind == JsonValueKind.Array)
            foreach (var child in element.EnumerateArray()) RejectDuplicates(child);
    }
    private static InvalidDataException Invalid() => new("Package metadata or Publish ZIP layout is invalid.");
}
